public class JSTypeSystem_getTypeWithProperty_TriageGen0Test {

    private AbstractCompiler compiler;
    private JSTypeSystem typeSystem;

    @Before
    public void setUp() {
        compiler = createCompiler();
        typeSystem = new JSTypeSystem(compiler);
    }

    @Test
    public void testGetTypeWithProperty_NullWhenNotObjectTypeAndNoAutobox() {
        JSType nonObjectType = mock(JSType.class);
        when(nonObjectType.autoboxesTo()).thenReturn(null);

        ObjectType result = typeSystem.getTypeWithProperty("prop", nonObjectType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_AutoboxesToObjectType() {
        JSType primitiveType = mock(JSType.class);
        ObjectType objectType = mock(ObjectType.class);

        when(primitiveType.autoboxesTo()).thenReturn(objectType);
        // Mocking prototype chain behavior for the autoboxed type
        when(objectType.getImplicitPrototype()).thenReturn(null);
        when(objectType.hasOwnProperty("prop")).thenReturn(false);

        ObjectType result = typeSystem.getTypeWithProperty("prop", primitiveType);
        // Since it's not found in prototype chain, result is null (foundType initialized to null)
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_ReturnsNullForPrototypeField() {
        ObjectType objType = mock(ObjectType.class);
        // Even if it has the property, "prototype" should return null
        when(objType.hasOwnProperty("prototype")).thenReturn(true);

        ObjectType result = typeSystem.getTypeWithProperty("prototype", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_FindsHighestPropertyInChain() {
        ObjectType root = mock(ObjectType.class);
        ObjectType middle = mock(ObjectType.class);
        ObjectType leaf = mock(ObjectType.class);

        // Setup chain: leaf -> middle -> root -> null
        // We want to ensure it finds 'root' if 'root' has the property, 
        // even if 'middle' also has it, because the loop continues to the top.
        // Actually, the logic says: "find the highest place (if any) that this appears".
        // The loop goes leaf -> middle -> root. 
        // If middle has it, foundType = middle. If root has it, foundType = root.

        when(leaf.getImplicitPrototype()).thenReturn(middle);
        when(middle.getImplicitPrototype()).thenReturn(root);
        when(root.getImplicitPrototype()).thenReturn(null);

        when(leaf.hasOwnProperty("prop")).thenReturn(true);
        when(middle.hasOwnProperty("prop")).thenReturn(true);
        when(root.hasOwnProperty("prop")).thenReturn(true);

        ObjectType result = typeSystem.getTypeWithProperty("prop", leaf);
        assertEquals(root, result);
    }

    @Test
    public void testGetTypeWithProperty_FindsPropertyInMiddleOfChain() {
        ObjectType root = mock(ObjectType.class);
        ObjectType middle = mock(ObjectType.class);
        ObjectType leaf = mock(ObjectType.class);

        when(leaf.getImplicitPrototype()).thenReturn(middle);
        when(middle.getImplicitPrototype()).thenReturn(root);
        when(root.getImplicitPrototype()).thenReturn(null);

        when(leaf.hasOwnProperty("prop")).thenReturn(false);
        when(middle.hasOwnProperty("prop")).thenReturn(true);
        when(root.hasOwnProperty("prop")).thenReturn(false);

        ObjectType result = typeSystem.getTypeWithProperty("prop", leaf);
        assertEquals(middle, result);
    }

    @Test
    public void testGetTypeWithProperty_NoPropertyFoundInChain() {
        ObjectType objType = mock(ObjectType.class);
        when(objType.getImplicitPrototype()).thenReturn(null);
        when(objType.hasOwnProperty("nonexistent")).thenReturn(false);

        ObjectType result = typeSystem.getTypeWithProperty("nonexistent", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_CircularPrototypeReturnsNull() {
        ObjectType objType = mock(ObjectType.class);
        // Simulate objType.getImplicitPrototype() == objType
        when(objType.getImplicitPrototype()).thenReturn(objType);
        when(objType.hasOwnProperty("prop")).thenReturn(true);

        // The loop condition is: objType != null && objType.getImplicitPrototype() != objType
        // If they are equal, the loop never executes.
        ObjectType result = typeSystem.getTypeWithProperty("prop", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_IsObjectTypeDirectly() {
        ObjectType objType = mock(ObjectType.class);
        when(objType.getImplicitPrototype()).thenReturn(null);
        when(objType.hasOwnProperty("prop")).thenReturn(true);

        ObjectType result = typeSystem.getTypeWithProperty("prop", objType);
        assertEquals(objType, result);
    }
}
